19	const componentPremium = (count: number): number =>
20	  count === BLOCK_SIZE ? BLOCK_PRICE : count * COMPONENT_PRICE;
21	
22	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
