45	const PROCESSING_FEE = 5;
46	const FIRST_INSURANCE_RATE = 0.1;
47	const LOYALTY_RATE = 0.2;
48	const LOYALTY_MIN_YEARS = 2;
49	const HIGH_ENCHANTMENT_RATE = 0.3;
50	const HIGH_ENCHANTMENT_MIN = 5;
51	const CURSE_RATE = 0.5;
52	const FOLLOWUP_RATE = 0.15;
53	
54	const isHighlyEnchanted = (item: Item): boolean =>
55	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_MIN;
56	
57	const itemSurcharge = (item: Item): number => {
58	  const surchargeOf = (applies: boolean, rate: number): number =>
59	    applies ? priceOf(item) * rate : 0;
60	
61	  return (
62	    surchargeOf(item.cursed ?? false, CURSE_RATE) +
63	    surchargeOf(isHighlyEnchanted(item), HIGH_ENCHANTMENT_RATE)
64	  );
65	};
