149	const rejectDamageWhere = (
150	  damages: Damage[],
151	  isInvalid: (damage: Damage) => boolean,
152	  describe: (damage: Damage) => string,
153	): void => {
154	  const offender = damages.find(isInvalid);
155	  if (offender) {
156	    throw new Error(describe(offender));
157	  }
158	};
