160	const rejectDamagesNotInPolicy: ClaimCheck = (policy, damages) =>
161	  rejectDamageWhere(
162	    damages,
163	    (damage) => !policy.items.some((item) => item.type === damage.itemType),
164	    (damage) => `Item not in policy: ${damage.itemType}`,
165	  );
166	
167	const rejectNegativeAmounts: ClaimCheck = (_policy, damages) =>
168	  rejectDamageWhere(
169	    damages,
170	    (damage) => damage.amount < 0,
171	    (damage) => `Negative damage amount: ${damage.amount}`,
172	  );
