174	const rejectOverclaimedTypes: ClaimCheck = (policy, damages) => {
175	  const insuredCounts = countByType(policy.items);
176	  const damageCounts: Record<string, number> = {};
177	  for (const damage of damages) {
178	    damageCounts[damage.itemType] = (damageCounts[damage.itemType] ?? 0) + 1;
179	    if (damageCounts[damage.itemType] > (insuredCounts[damage.itemType] ?? 0)) {
180	      throw new Error(`More ${damage.itemType} damages than insured`);
181	    }
182	  }
183	};
