200	const settleClaim = (policy: Policy, damages: Damage[]): number => {
201	  const desired = payout(damages, policy.items);
202	  const actual = Math.min(desired, policy.remainingCap);
203	  policy.remainingCap -= actual;
204	  return actual;
205	};
