207	export const runScenario = (scenario: Scenario): { results: unknown[] } => {
208	  const policies: Record<number, Policy> = {};
209	  let quoteCount = 0;
210	  const results: unknown[] = [];
211	
212	  scenario.steps.forEach((step, index) => {
213	    if (step.op === "quote") {
214	      validateQuoteItems(step.items);
215	      const opts = {
216	        yearsWithMHPCO: scenario.customer.yearsWithMHPCO,
217	        isFollowUp: quoteCount > 0,
218	      };
219	      quoteCount += 1;
220	      policies[index] = openPolicy(step.items);
221	      results.push({ premium: premium(step.items, opts) });
222	    } else {
223	      const policy = policies[step.policy];
224	      validateClaimDamages(policy, step.incident.damages);
225	      const paidOut = settleClaim(policy, step.incident.damages);
226	      results.push({ payout: paidOut, remainingCap: policy.remainingCap });
227	    }
228	  });
229	
230	  return { results };
231	};
